message.content:
{
  "css": "#booking-layout {
  border-top: 1px solid #ededf0;
  padding: 20px 0;
}

.booking-host-title {
  margin: 0 0 4px 0;
  font-size: 16px;
  font-weight: 700;
  color: #202024;
  line-height: 1.4;
}

.booking-host-subtitle {
  margin: 0;
  font-size: 14px;
  color: #60606a;
  line-height: 1.5;
}

#booking-actions {
  padding-top: 20px;
}

.booking-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  margin: 0;
  padding: 0;
  background: transparent;
  border: none;
  cursor: pointer;
  color: #60606a;
  transition: color 0.2s ease, background-color 0.2s ease;
  border-radius: 6px;
}

.booking-icon-btn:hover {
  background-color: #f4f4f5;
  color: #202024;
}

.booking-icon-btn:active {
  background-color: #e4e4e7;
}

.booking-icon-btn img {
  width: 24px;
  height: 24px;
  display: block;
  pointer-events: none;
}

.booking-primary-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 52px;
  min-width: 0;
  padding: 0 24px;
  margin: 0;
  background-color: #5146d7;
  color: #ffffff;
  font-size: 16px;
  font-weight: 700;
  line-height: 1.5;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: background-color 0.2s ease, opacity 0.2s ease;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.booking-primary-btn:hover {
  background-color: #4338ca;
}

.booking-primary-btn:active {
  background-color: #3b2fa6;
  opacity: 0.95;
}

.booking-note {
  margin-top: 12px;
  font-size: 14px;
  color: #60606a;
  line-height: 1.6;
}"
}
